<template>
  <div class="page-container sil-page">
    <div class="page-head"><div><h2>青贮作物收储</h2><p>收储主体或委托当地县级农业农村部门代办，在线申报收储的青贮饲料种植品种、价格和重量。</p></div><el-tag type="warning">待处理 {{ rows.filter(r => r.status === 'pending').length }} 条</el-tag></div>
    <div class="panel">
      <el-form :inline="true" class="filters"><el-form-item label="申报来源"><el-select v-model="filters.source" style="width:170px"><el-option label="全部" value="all"/><el-option label="收储主体在线申报" value="subject"/><el-option label="县级农业农村部门代办" value="county"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" placeholder="待处理" clearable style="width:130px"><el-option label="待处理" value="pending"/><el-option label="已完成" value="filed"/><el-option label="退回补正" value="returned"/><el-option label="已驳回" value="rejected"/></el-select></el-form-item><el-form-item label="关键词"><el-input v-model="filters.keyword" clearable placeholder="主体、品种或编号"/></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form>
      <el-table :data="filteredRows" stripe border><el-table-column prop="sourceName" label="申报来源" width="180"><template #default="{row}"><el-tag size="small" :type="row.source === 'county' ? 'warning' : 'success'">{{ row.sourceName }}</el-tag></template></el-table-column><el-table-column prop="id" label="申报编号" width="165"/><el-table-column prop="subjectName" label="收储主体" min-width="190"/><el-table-column prop="cropName" label="青贮种植品种" width="140"/><el-table-column prop="price" label="收储价格（元/吨）" width="155" align="right"/><el-table-column prop="weight" label="收储重量（吨）" width="140" align="right"/><el-table-column prop="createdAt" label="申报时间" width="110"/><el-table-column prop="status" label="状态" width="95"><template #default="{row}"><el-tag size="small" :type="tagType(row.status)">{{ statusName(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{ row.status === 'pending' ? '处理收储' : '查看详情' }}</el-button><el-button link @click="showTrail(row)">留痕</el-button></template></el-table-column></el-table><el-empty v-if="!filteredRows.length" description="暂无青贮作物收储数据"/>
    </div>
    <el-dialog v-model="visible" title="青贮作物收储详情" width="860px"><template v-if="current"><el-descriptions :column="3" border><el-descriptions-item label="申报编号">{{ current.id }}</el-descriptions-item><el-descriptions-item label="申报来源">{{ current.sourceName }}</el-descriptions-item><el-descriptions-item label="收储主体">{{ current.subjectName }}</el-descriptions-item><el-descriptions-item label="青贮种植品种">{{ current.cropName || current.crop }}</el-descriptions-item><el-descriptions-item label="收储价格">{{ current.price }} 元/吨</el-descriptions-item><el-descriptions-item label="收储重量">{{ current.weight }} 吨</el-descriptions-item><el-descriptions-item label="联系人">{{ current.contact || '—' }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ current.phone || '—' }}</el-descriptions-item><el-descriptions-item label="申报时间">{{ current.createdAt }}</el-descriptions-item></el-descriptions><div class="sub-title">审核处理留痕</div><el-timeline><el-timeline-item v-for="(item,index) in current.auditTrail" :key="index" :timestamp="item.time">{{ item.action }}<span class="trail-user">{{ item.user }}</span><div v-if="item.opinion" class="trail-opinion">{{ item.opinion }}</div></el-timeline-item></el-timeline><el-input v-if="current.status === 'pending'" v-model="opinion" type="textarea" :rows="3" placeholder="填写处理意见；退回或驳回时必填"/></template><template #footer><el-button @click="visible=false">关闭</el-button><template v-if="current?.status === 'pending'"><el-button type="warning" @click="audit('return')">退回补正</el-button><el-button type="danger" @click="audit('reject')">驳回</el-button><el-button type="primary" @click="audit('pass')">完成收储</el-button></template></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { fetchDeclarations, fetchSupplements, auditDeclaration, auditSupplement } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const current = ref(null); const visible = ref(false); const opinion = ref(''); const filters = reactive({ source: 'all', status: 'pending', keyword: '' }); const statusName = (s) => ({ pending: '待处理', filed: '已完成', returned: '退回补正', rejected: '已驳回' }[s] || s); const tagType = (s) => ({ pending: 'warning', filed: 'success', returned: 'warning', rejected: 'danger' }[s] || 'info'); const isCountyAgent = (r) => r.source === 'county' || (r.auditTrail || []).some((item) => `${item.action}${item.user}`.includes('代办') || `${item.action}${item.user}`.includes('农业农村部门')); const filteredRows = computed(() => rows.value.filter((r) => (filters.source === 'all' || r.source === filters.source) && (!filters.status || r.status === filters.status) && (!filters.keyword || `${r.id}${r.subjectName}${r.cropName || ''}${r.variety || ''}`.includes(filters.keyword)))); const load = async () => { const [declarations, supplements] = await Promise.all([fetchDeclarations(userStore.role), fetchSupplements(userStore.role)]); rows.value = declarations.map((r) => ({ ...r, source: isCountyAgent(r) ? 'county' : 'subject', sourceName: isCountyAgent(r) ? '县级农业农村部门代办' : '收储主体在线申报' })).concat(supplements.map((r) => ({ ...r, source: 'county', sourceName: '县级农业农村部门代办', cropName: r.crop, price: r.price || 0, weight: r.supplementArea, status: r.status }))) }; const reset = () => { Object.assign(filters, { source: 'all', status: 'pending', keyword: '' }); load() }; const open = (row) => { current.value = row; opinion.value = ''; visible.value = true }; const showTrail = (row) => open(row); const audit = async (action) => { if (action !== 'pass' && !opinion.value.trim()) return ElMessage.warning('请填写处理意见'); try { await ElMessageBox.confirm(`确认${action === 'pass' ? '完成收储' : action === 'return' ? '退回补正' : '驳回'}该申报吗？`, '处理确认', { type: action === 'pass' ? 'success' : 'warning' }) } catch { return } const result = current.value.isSupplement ? await auditSupplement(current.value.id, action, opinion.value, userStore.role.name, userStore.role) : await auditDeclaration(current.value.id, action, opinion.value, userStore.role); if (!result.success) return ElMessage.error(result.message || '处理失败'); ElMessage.success('收储处理结果已保存'); visible.value = false; load() }; onMounted(load)
</script>
<style scoped lang="scss">.sil-page{overflow:auto}.page-head{display:flex;justify-content:space-between;margin-bottom:14px}.page-head h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px}.sub-title{margin:18px 0 10px;padding-left:8px;border-left:3px solid var(--ah-primary);font-weight:600}.trail-user{margin-left:12px;color:#8492a6}.trail-opinion{margin-top:4px;color:#667085}</style>